    'admin_leader_operating_system.leader.opportunity_modal_intro' => 'Marja de creștere este acum de %s. Mai jos sunt schimbările și acțiunile care au cele mai mari șanse să-l ajute pe acest colaborator să progreseze mai repede și să-și îmbunătățească rezultatul.',
    'admin_leader_operating_system.leader.opportunity_modal_empty' => 'Momentan nu există semnale suplimentare, dar accentul ar trebui să rămână pe CTA-uri mai puternice, o conversie mai bună și un parcurs mai simplu către înregistrare sau achiziție.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.label' => 'Mărește ponderea clicurilor care duc la magazinul online sau la ofertele de reducere',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.text' => 'Colaboratorul are %s clicuri în total, dar doar %s%% dintre acestea duc la magazinul online Forever sau la pagini cu reduceri.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Mută mai sus pe pagină CTA-ul către magazinul online sau reducere și repetă-l spre partea de jos a profilului sau a articolului de pe blog.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Adaugă un îndemn mai clar la acțiune pe traseul principal de trafic, astfel încât vizitatorii să ajungă la o destinație Forever, nu doar la conținut informativ.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'Pentru sursa %s, testează un îndemn la acțiune mai clar, care îi duce pe utilizatori direct din conținut către magazinul online Forever sau către pagina cu reducerea.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Verifică dacă blocurile pentru blog, vânzări și reduceri fac traseul de cumpărare suficient de vizibil și dacă sunt afișate destul de des.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.label' => 'Transformă accesările magazinului online în înregistrări sau achiziții',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.text' => 'Colaboratorul are deja %s clicuri către magazinul online, dar nu a avut nicio înscriere în această perioadă.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_1' => 'Verifică dacă, după clic, se deschide URL-ul de recomandare corect și dacă ajungi la pagina sau la ecranul magazinului online dorit, fără erori.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_2' => 'Îmbunătățește mesajul înainte de clic: explică ce primește vizitatorul, de ce să apese acum și ce se întâmplă după ce ajunge pe pagina Forever.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Testează o cale mai simplă de înregistrare sau cumpărare și elimină pașii care creează confuzie după primul clic.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Dacă cea mai mare parte a traficului provine din %s, verifică dacă pagina de destinație este localizată corect și deschide versiunea potrivită pentru piață.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.label' => 'Crește rata de conversie pe măsură ce traficul crește',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.text' => 'Traficul crește cu %s%%, dar rata de înregistrare este de doar %s%%, așa că clicurile suplimentare nu aduc încă suficiente rezultate.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Păstrează sursa care generează creștere, dar îmbunătățește textul CTA și mesajul introductiv, astfel încât să identifice mai bine intenția de cumpărare.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'Consolidează încrederea înainte de îndemnul la acțiune: adaugă o mărturie, un rezultat, o mini secțiune de întrebări frecvente sau o explicație clară despre ce se întâmplă după ce se dă clic.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Compară sursele clicurilor și continuă să prioritizezi doar canalele care aduc înscrieri sau contacte potențiali de calitate mai bună, nu doar un volum mare de trafic.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Folosește interesul existent pentru a crea un parcurs de vânzare mai eficient',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.text' => 'Aplicația generează deja semnale prin WhatsApp (%1$s), produse (%2$s) și înscrieri (%3$s), dar acest lucru încă nu îi îndrumă pe suficienți oameni către magazin.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_1' => 'Afișează o cale principală clară către magazin, deasupra celorlalte opțiuni de vânzare.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_2' => 'Asigură-te că mesajul din conținut, WhatsApp și blocurile de vânzări indică același pas următor.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_3' => 'Păstrează blocurile care stârnesc interesul, dar delimitează clar locul în care trebuie să aibă loc imediat clicul pentru achiziție sau înscriere.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.label' => 'Menține elanul prin optimizări mai mici',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.text' => 'Potențialul de creștere nu este mare din cauza unei singure probleme majore, ci datorită unor oportunități mai mici de îmbunătățire.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_1' => 'Continuă să direcționezi traficul către punctele CTA cele mai eficiente, care funcționează deja bine.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_2' => 'Continuă să testezi formularea titlului, ordinea CTA-urilor și elementele care inspiră încredere pentru a menține sau a reduce scorul oportunității.',
